}

import { Item } from '@liulidesign/core/Item';
import { Badge } from '@liulidesign/core/Badge';

/** In a pressable row the end content is not read, so the status is repeated in the description. */
export function InARow() {
  return (
    <view className="overflow-hidden rounded-container border border-text/12 bg-surface">
      <Item
        label="Invoice 2041"
        description="Overdue, due 3 May"
        endContent={<Badge label="Overdue" tone="danger" size="sm" />}
        hasChevron
        onClick={() => {}}
        data-testid="invoice"
      />
    </view>
  );
}

import { useLocal } from '@lingxia/view';
import { Banner } from '@liulidesign/core/Banner';

/** A problem with one way out, that the person can also put aside. */
export function Payment() {
  const shown = useLocal(true);
  const updated = useLocal(false);
  if (!shown.value) return <text className="text-footnote text-muted">Dismissed. It comes back on the next visit.</text>;
  return (
    <Banner
      tone="warning"
      title="Your card expires this month"
      message="Update it before 30 June to keep syncing across devices."
      action={{ label: updated.value ? 'Card updated' : 'Update card', onClick: () => updated.set(true) }}
      onDismiss={() => shown.set(false)}
      dismissLabel="Dismiss"
      data-testid="payment"
    />
  );
}

import { Banner } from '@liulidesign/core/Banner';

export function Tones() {
  return (
    <view className="gap-3">
      <Banner tone="neutral" title="Read only" message="An admin locked this notebook." />
      <Banner tone="info" title="Sharing is changing" message="From July, shared notebooks need a Team plan." />
      <Banner tone="success" title="All notes synced" />
      <Banner tone="warning" title="Storage almost full" message="You have used 9.6 of 10 GB." />
      <Banner tone="danger" title="Sync stopped" message="We could not reach the server. Your changes are kept on this device." />
    </view>
  );
}

import { useLocal } from '@lingxia/view';
import { Banner } from '@liulidesign/core/Banner';

/** At the top of a list it is about, before the content. */
export function OverList() {
  const retried = useLocal(false);
  return (
    <view className="gap-3">
      <Banner
        tone="danger"
        title={retried.value ? 'Still offline' : 'Sync stopped'}
        message="Changes are kept on this device until the connection returns."
        action={{ label: 'Retry now', onClick: () => retried.set(true) }}
        data-testid="sync"
      />
      <view className="overflow-hidden rounded-container border border-text/12 bg-surface divide-y divide-text/8">
        {['Q3 plan', 'Reading list', 'Interview notes'].map(note => (
          <view key={note} className="px-4 py-3"><text className="text-body text-text">{note}</text></view>
        ))}
      </view>
    </view>
  );
}

import { useLocal } from '@lingxia/view';
import { Button } from '@liulidesign/core/Button';
import { Item, ItemList } from '@liulidesign/core/Item';
import { BottomSheet } from '@liulidesign/core/BottomSheet';

const moveTargets = ['Inbox', 'Travel', 'Work', 'Recipes'];

/** Choosing where a note goes: a sheet as tall as its list, dragged down or tapped outside to cancel. */
export function MoveTo() {
  const open = useLocal('open', false);
  const folder = useLocal('folder', 'Inbox');
  return (
    <view className="gap-3">
      <Button label="Move note" width="content" onClick={() => open.set(true)} data-testid="move-open" />
      <text className="text-footnote text-muted" data-testid="folder">{`In ${folder.value}`}</text>
      <BottomSheet isOpen={open.value} onOpenChange={next => open.set(next)} label="Move to" data-testid="move">
        <ItemList label="Folders">
          {moveTargets.map(name => (
            <Item key={name} label={name} onClick={() => { folder.set(name); open.set(false); }} data-testid={`folder-${name}`} />
          ))}
        </ItemList>
      </BottomSheet>
    </view>
  );
}

import { useLocal } from '@lingxia/view';
import { Button } from '@liulidesign/core/Button';
import { BottomSheet } from '@liulidesign/core/BottomSheet';

const comments = [
  ['Ana', 'Can we move the review to Thursday?'],
  ['Kai', 'Thursday works. I will update the plan.'],
  ['Mira', 'Added the budget numbers under Q3.'],
  ['Ana', 'Thanks. The hiring section still needs dates.'],
  ['Kai', 'I will add them after the sync.'],
  ['Mira', 'Linked the research notes as well.'],
] as const;

/** A long list: the sheet opens halfway and drags up to nearly the full height. */
export function Comments() {
  const open = useLocal('open', false);
  return (
    <view className="gap-3">
      <Button label="Show comments" width="content" onClick={() => open.set(true)} data-testid="comments-open" />
      <BottomSheet
        isOpen={open.value}
        onOpenChange={next => open.set(next)}
        label="Comments"
        closeLabel="Close"
        detents="expandable"
        data-testid="comments"
      >
        {comments.map(([who, text], index) => (
          <view key={`c${index}`} className="gap-0.5">
            <text className="text-footnote font-semibold text-text">{who}</text>
            <text className="text-body text-text">{text}</text>
          </view>
        ))}
      </BottomSheet>
    </view>
  );
}

import { useLocal } from '@lingxia/view';
import { Button } from '@liulidesign/core/Button';
import { BottomSheet } from '@liulidesign/core/BottomSheet';

/** A step that must be answered: no drag off, no tap outside. */
export function Required() {
  const open = useLocal('open', false);
  const answer = useLocal('answer', '');
  return (
    <view className="gap-3">
      <Button label="Leave notebook" variant="destructive" width="content" onClick={() => open.set(true)} data-testid="leave-open" />
      {answer.value !== '' && <text className="text-footnote text-muted" data-testid="answer">{answer.value}</text>}
      <BottomSheet
        isOpen={open.value}
        onOpenChange={next => open.set(next)}
        label="Leave this notebook?"
        description="You lose access to its notes until someone invites you again."
        dismissOn="none"
        data-testid="leave"
        actions={
          <>
            <Button label="Stay" onClick={() => { answer.set('Stayed'); open.set(false); }} data-testid="stay" />
            <Button label="Leave" variant="destructive" onClick={() => { answer.set('Left'); open.set(false); }} data-testid="leave-confirm" />
          </>
        }
      />
    </view>
  );
}

import { Button } from '@liulidesign/core/Button';

export function Variants() {
  return (
    <view className="flex-row flex-wrap gap-2">
      <Button label="Save changes" variant="primary" data-testid="primary" />
      <Button label="Preview" />
      <Button label="Skip" variant="ghost" />
      <Button label="Delete draft" variant="destructive" />
    </view>
  );
}

import { Button } from '@liulidesign/core/Button';

export function Sizes() {
  return (
    <view className="flex-row flex-wrap items-center gap-2">
      <Button label="Small" size="sm" />
      <Button label="Medium" />
      <Button label="Large" size="lg" />
    </view>
  );
}

import { Button } from '@liulidesign/core/Button';

/** An icon before the label says what kind of action it is; one after it says where the button leads. */
export function WithIcons() {
  return (
    <view className="flex-row flex-wrap gap-3">
      <Button label="New note" variant="primary" startIcon="add" data-testid="new-note" />
      <Button label="Share" startIcon="share" />
      <Button label="Continue" endIcon="arrow-end" data-testid="continue-on" />
      <Button label="Delete" variant="destructive" startIcon="delete" />
    </view>
  );
}

import { useView, type View } from '@lingxia/view';
import { Button } from '@liulidesign/core/Button';

type Actions = { publish(): Promise<void> };

/** `clickAction` takes a Logic action as it is; the button shows loading until it settles. */
export function AsyncAction() {
  const { actions } = useView() as View<Actions>;
  return <Button label="Publish" variant="primary" width="content" clickAction={() => actions.publish()} data-testid="publish" />;
}

import { useLocal } from '@lingxia/view';
import { Button } from '@liulidesign/core/Button';

/** The reason is read after the label while disabled. Pass translated copy; Liuli ships none. */
export function DisabledWithReason() {
  const agreed = useLocal('agreed', false);
  return (
    <view className="gap-2">
      <Button
        label="Continue"
        variant="primary"
        width="fill"
        isDisabled={!agreed.value}
        disabledMessage="Accept the terms first"
        data-testid="continue"
      />
      <Button
        label={agreed.value ? 'Withdraw consent' : 'Accept the terms'}
        variant="ghost"
        width="content"
        onClick={() => agreed.set(!agreed.value)}
        data-testid="toggle-terms"
      />
    </view>
  );
}

import { useLocal } from '@lingxia/view';
import { Button } from '@liulidesign/core/Button';
import { ButtonGroup } from '@liulidesign/core/ButtonGroup';

/** Actions on one thing sit together, the main one last. */
export function Actions() {
  const outcome = useLocal('outcome', 'Draft');
  return (
    <view className="gap-3">
      <ButtonGroup label="Draft actions" data-testid="actions">
        <Button label="Discard" variant="ghost" onClick={() => outcome.set('Discarded')} data-testid="discard" />
        <Button label="Save" onClick={() => outcome.set('Saved')} data-testid="save" />
        <Button label="Publish" variant="primary" onClick={() => outcome.set('Published')} data-testid="publish" />
      </ButtonGroup>
      <text role="status" data-testid="outcome" className="text-footnote text-muted">{outcome.value}</text>
    </view>
  );
}

import { Button } from '@liulidesign/core/Button';
import { ButtonGroup } from '@liulidesign/core/ButtonGroup';

/** Attached, for actions of one kind: the buttons share edges and the group is one shape. */
export function Attached() {
  return (
    <ButtonGroup label="History" isAttached data-testid="history">
      <Button label="Undo" startIcon="undo" data-testid="undo" />
      <Button label="Redo" startIcon="redo" data-testid="redo" />
      <Button label="Reset" data-testid="reset" />
    </ButtonGroup>
  );
}

import { IconButton } from '@liulidesign/core/IconButton';
import { ButtonGroup } from '@liulidesign/core/ButtonGroup';

export function IconsAttached() {
  return (
    <ButtonGroup label="Zoom" isAttached variant="secondary" data-testid="zoom">
      <IconButton label="Zoom out" icon="remove" data-testid="zoom-out" />
      <IconButton label="Zoom in" icon="add" />
      <IconButton label="Fit to screen" icon="expand" />
    </ButtonGroup>
  );
}

import { Button } from '@liulidesign/core/Button';
import { ButtonGroup } from '@liulidesign/core/ButtonGroup';

export function Sizes() {
  return (
    <view className="gap-4">
      <ButtonGroup label="Small" isAttached size="sm" data-testid="small">
        <Button label="Day" data-testid="small-day" />
        <Button label="Week" />
        <Button label="Month" />
      </ButtonGroup>
      <ButtonGroup label="Large" isAttached size="lg">
        <Button label="Day" data-testid="large-day" />
        <Button label="Week" />
        <Button label="Month" />
      </ButtonGroup>
    </view>
  );
}

import { Button } from '@liulidesign/core/Button';
import { IconButton } from '@liulidesign/core/IconButton';
import { ButtonGroup } from '@liulidesign/core/ButtonGroup';

/** A toolbar over content: icon buttons in a quiet group, a labelled action apart from it. */
export function Toolbar() {
  return (
    <view className="flex-row items-center justify-between gap-3">
      <ButtonGroup label="Message actions" size="sm" data-testid="message">
        <IconButton label="Reply" icon="message" />
        <IconButton label="Forward" icon="send" />
        <IconButton label="Delete" icon="delete" />
      </ButtonGroup>
      <Button label="Archive" size="sm" startIcon="folder" />
    </view>
  );
}

import { Card } from '@liulidesign/core/Card';

export function Variants() {
  return (
    <view className="gap-3">
      <Card data-testid="outlined">
        <text className="text-callout font-semibold text-text">Outlined</text>
        <text className="text-footnote text-muted">Sits on the page.</text>
      </Card>
      <Card variant="raised">
        <text className="text-callout font-semibold text-text">Raised</text>
        <text className="text-footnote text-muted">Rests one step above the page.</text>
      </Card>
      <Card variant="sunken">
        <text className="text-callout font-semibold text-text">Sunken</text>
        <text className="text-footnote text-muted">Groups content inside another surface.</text>
      </Card>
    </view>
  );
}

import { Button } from '@liulidesign/core/Button';
import { Card, ClickableCard } from '@liulidesign/core/Card';

/** Actions go in a plain Card, never in a ClickableCard. */
export function WithActions() {
  return (
    <Card>
      <text role="heading" headingLevel={3} className="text-callout font-semibold text-text">Back up your notes</text>
      <text className="text-footnote text-muted">Keep a copy on another device in case this one is lost.</text>
      <view className="flex-row justify-end gap-2">
        <Button label="Not now" variant="ghost" size="sm" />
        <Button label="Turn on" variant="primary" size="sm" data-testid="turn-on" />
      </view>
    </Card>
  );
}

import { useLocal } from '@lingxia/view';
import { ClickableCard, ClickableCardGroup } from '@liulidesign/core/Card';

const plans = [
  { id: 'monthly', name: 'Monthly', price: '€4 a month' },
  { id: 'yearly', name: 'Yearly', price: '€40 a year' },
] as const;

/** Choosing one of several: the cards are a radio group, and the chosen one is checked. */
export function Choice() {
  const plan = useLocal<string | null>('plan', 'monthly');
  return (
    <ClickableCardGroup label="Plan" bind={plan} className="flex-row" data-testid="plans">
      {plans.map(item => (
        <ClickableCard
          key={item.id}
          value={item.id}
          label={`${item.name}, ${item.price}`}
          className="grow basis-0"
          data-testid={`plan-${item.id}`}
        >
          <text className="text-callout font-semibold text-text">{item.name}</text>
          <text className="text-footnote text-muted">{item.price}</text>
        </ClickableCard>
      ))}
    </ClickableCardGroup>
  );
}

import { useLocal } from '@lingxia/view';
import { CheckboxInput } from '@liulidesign/core/CheckboxInput';

export function Basic() {
  const digest = useLocal('digest', true);
  return <CheckboxInput bind={digest} label="Weekly digest" description="A summary of your notes every Monday." data-testid="digest" />;
}

import { useLocal } from '@lingxia/view';
import { CheckboxInput } from '@liulidesign/core/CheckboxInput';

/** Owned by the app: the checkbox reports, the app decides. */
export function Controlled() {
  const accepted = useLocal('accepted', false);
  return (
    <CheckboxInput
      value={accepted.value}
      onChange={next => accepted.set(next)}
      label="I accept the terms of service"
      isRequired
      status={accepted.value ? undefined : { type: 'error', message: 'Accept the terms to create the account.' }}
      data-testid="terms"
    />
  );
}

import { useLocal } from '@lingxia/view';
import { CheckboxInput } from '@liulidesign/core/CheckboxInput';

export function Sizes() {
  const small = useLocal('small', false);
  const medium = useLocal('medium', true);
  const large = useLocal('large', false);
  return (
    <view className="gap-2">
      <CheckboxInput bind={small} label="Small" size="sm" />
      <CheckboxInput bind={medium} label="Medium" />
      <CheckboxInput bind={large} label="Large" size="lg" />
    </view>
  );
}

import { useLocal } from '@lingxia/view';
import { CheckboxList } from '@liulidesign/core/CheckboxList';

const topics = [
  { value: 'mentions', label: 'Mentions', description: 'When someone names you in a note.' },
  { value: 'comments', label: 'Comments', description: 'Replies on notes you wrote.' },
  { value: 'digest', label: 'Weekly digest' },
];

/** Any number of the options can be on; the value is the list of those that are. */
export function Notifications() {
  const chosen = useLocal<readonly string[]>('topics', ['mentions']);
  return (
    <view className="gap-3">
      <CheckboxList label="Notify me about" bind={chosen} options={topics} data-testid="topics" />
      <text role="status" data-testid="chosen" className="text-footnote text-muted">{chosen.value.length === 0 ? 'Nothing chosen' : chosen.value.join(', ')}</text>
    </view>
  );
}

import { useLocal } from '@lingxia/view';
import { CheckboxList } from '@liulidesign/core/CheckboxList';

const days = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri'].map(day => ({ value: day.toLowerCase(), label: day }));

/** A message about the group as a whole, when the choice so far cannot stand. */
export function AtLeastOne() {
  const chosen = useLocal<readonly string[]>('days', []);
  return (
    <CheckboxList
      label="Office days"
      description="We book a desk for each day you choose."
      isRequired
      bind={chosen}
      options={days}
      status={chosen.value.length === 0 ? { type: 'error', message: 'Choose at least one day.' } : undefined}
      data-testid="days"
    />
  );
}

import { useLocal } from '@lingxia/view';
import { CheckboxList } from '@liulidesign/core/CheckboxList';

const toppings = [
  { value: 'olives', label: 'Olives' },
  { value: 'mushrooms', label: 'Mushrooms' },
  { value: 'anchovies', label: 'Anchovies', description: 'Sold out today.', isDisabled: true },
];

export function WithUnavailable() {
  const chosen = useLocal<readonly string[]>('toppings', ['olives']);
  return <CheckboxList label="Toppings" bind={chosen} options={toppings} data-testid="toppings" />;
}

import { useLocal } from '@lingxia/view';
import { CheckboxList } from '@liulidesign/core/CheckboxList';

export function Sizes() {
  const chosen = useLocal<readonly string[]>('sized', ['a']);
  const two = [{ value: 'a', label: 'First' }, { value: 'b', label: 'Second' }];
  return (
    <view className="grid grid-cols-2 gap-4">
      <CheckboxList label="Small" size="sm" bind={chosen} options={two} data-testid="small" />
      <CheckboxList label="Large" size="lg" bind={chosen} options={two} data-testid="large" />
    </view>
  );
}

import { useLocal } from '@lingxia/view';
import { Combobox } from '@liulidesign/core/Combobox';

const countries = [
  'Argentina', 'Australia', 'Brazil', 'Canada', 'Chile', 'China', 'Egypt', 'France', 'Germany', 'India', 'Indonesia', 'Italy', 'Japan',
  'Kenya', 'Mexico', 'Morocco', 'Netherlands', 'Nigeria', 'Norway', 'Peru', 'Portugal', 'South Africa', 'South Korea', 'Spain', 'Sweden', 'Türkiye',
  'United Kingdom', 'United States', 'Vietnam',
].map(name => ({ value: name.toLowerCase().replace(/[^a-z]+/g, '-'), label: name }));

/** A long list found by typing: the field opens a search over its options. */
export function Country() {
  const country = useLocal('country', '');
  return (
    <Combobox
      label="Country"
      bind={country}
      options={countries}
      placeholder="Choose a country"
      searchLabel="Search countries"
      searchPlaceholder="Search"
      emptyLabel="No country matches"
      closeLabel="Close"
      data-testid="country"
    />
  );
}

import { useLocal } from '@lingxia/view';
import { Combobox } from '@liulidesign/core/Combobox';

const people = [
  { value: 'ana', label: 'Ana Lee', description: 'Design' },
  { value: 'ben', label: 'Ben Okafor', description: 'Engineering' },
  { value: 'chloe', label: 'Chloé Martin', description: 'Engineering' },
  { value: 'dev', label: 'Dev Patel', description: 'On leave until June', isDisabled: true },
  { value: 'emi', label: 'Emi Sato', description: 'Research' },
];

/** A second line tells apart options with similar names; one that cannot be chosen stays in the list, dimmed. */
export function Assignee() {
  const person = useLocal('person', 'ben');
  return (
    <Combobox
      label="Assignee"
      description="They are notified when the task changes."
      bind={person}
      options={people}
      searchLabel="Search people"
      emptyLabel="Nobody by that name"
      data-testid="assignee"
    />
  );
}

import { useLocal } from '@lingxia/view';
import { Combobox } from '@liulidesign/core/Combobox';

const airports = [
  { value: 'LIS', label: 'Lisbon', description: 'LIS · Humberto Delgado' },
  { value: 'LHR', label: 'London', description: 'LHR · Heathrow' },
  { value: 'LGW', label: 'London', description: 'LGW · Gatwick' },
  { value: 'NBO', label: 'Nairobi', description: 'NBO · Jomo Kenyatta' },
  { value: 'OSL', label: 'Oslo', description: 'OSL · Gardermoen' },
];

/** The app does the matching itself: here a code finds its airport as well as a city does. */
export function OwnMatching() {
  const airport = useLocal('airport', '');
  const typed = useLocal('typed', '');
  const text = typed.value.trim().toLowerCase();
  return (
    <Combobox
